const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon(
    [[[-118.40, 50.40],
      [-118.40, 50.00],
      [-117.80, 50.00],
      [-117.80, 50.40],
      [-118.40, 50.40]]],
    null, false); // Approximate region for Upper Arrow Lake, BC

  const date = '2018-10-22';
  const scale = 100; // Use a coarser scale to avoid memory issues for regional analysis, 100m for Sentinel-2
  const maxPixels = 1e9;

  // Function to mask clouds in Sentinel-2 images using QA60 band
  function maskS2Clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale reflectance bands
  }

  // 2. Data Acquisition & Check for Sentinel-2
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(geometry)
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80)); // Filter out very cloudy images initially

  // Check if collection is empty
  const s2Size = await s2Collection.size().getInfo();
  if (s2Size === 0) {
    console.log(`No Sentinel-2 images found for ${date} in the region.`);
    console.log('C1');
    return;
  }
  console.log(`Initial S2 images: ${s2Size}`);

  // Try to find morning and afternoon images by acquisition time.
  // Sentinel-2 overpasses are typically mid-morning. It's highly unlikely to get
  // true "morning" and "afternoon" images on the same day from Sentinel-2.
  // We'll try to find any distinct acquisition times.
  const morningImages = s2Collection.filter(ee.Filter.lt('system:time_start', ee.Date(date).advance(12, 'hour').millis()));
  const afternoonImages = s2Collection.filter(ee.Filter.gte('system:time_start', ee.Date(date).advance(12, 'hour').millis()));

  const morningSize = await morningImages.size().getInfo();
  const afternoonSize = await afternoonImages.size().getInfo();

  console.log(`Morning images (before 12:00 UTC): ${morningSize}`);
  console.log(`Afternoon images (12:00 UTC and later): ${afternoonSize}`);

  // Select the first image for "morning" and "afternoon" if available.
  // If only one distinct time, it might be the same image in both.
  const morningImage = morningImages.first();
  const afternoonImage = afternoonImages.first();

  if (!morningImage || !afternoonImage) {
    console.log('Could not find distinct morning and afternoon images for comparison.');
    console.log('C1');
    return;
  }

  const morningTime = ee.Date(morningImage.get('system:time_start')).format('HH:mm').getInfo();
  const afternoonTime = ee.Date(afternoonImage.get('system:time_start')).format('HH:mm').getInfo();

  console.log(`Morning image time: ${morningTime} UTC`);
  console.log(`Afternoon image time: ${afternoonTime} UTC`);

  // If the "morning" and "afternoon" images are the same (or very close in time),
  // we cannot perform a meaningful morning-to-afternoon comparison.
  if (morningImage.id().getInfo() === afternoonImage.id().getInfo()) {
    console.log('Only one distinct acquisition time found, cannot compare morning vs. afternoon.');
    console.log('C1');
    return;
  }

  // 3. Processing (Apply cloud mask and calculate cloud coverage)
  // We'll use the QA60 band to estimate 'fog' as cloud coverage.
  // The 'fog' here is represented by any detected cloud in the QA60 band.

  const calculateCloudCoverage = async (image, label) => {
    // Select the QA60 band directly for cloud detection
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;

    // A pixel is considered "cloudy" if either the cloud or cirrus bit is set.
    const cloudyPixels = qa.bitwiseAnd(cloudBitMask).neq(0)
      .or(qa.bitwiseAnd(cirrusBitMask).neq(0));

    // Calculate the total number of valid pixels in the region.
    // Use the B2 band (blue) as a reference for valid data extent.
    const totalPixels = image.select('B2').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: maxPixels
    }).get('B2');

    // Calculate the number of cloudy pixels.
    const numCloudyPixels = cloudyPixels.reduceRegion({
      reducer: ee.Reducer.sum(), // sum 1s for cloudy, 0s for clear
      geometry: geometry,
      scale: scale,
      maxPixels: maxPixels
    }).get('QA60');

    const total = await totalPixels.getInfo();
    const cloudy = await numCloudyPixels.getInfo();

    if (total === null || cloudy === null || total === 0) {
      console.log(`Error: Calculation failure for ${label} (total or cloudy pixels is null/zero).`);
      return null;
    }

    const coverage = (cloudy / total) * 100;
    console.log(`${label} Valid Pixels: ${total.toLocaleString()}`);
    console.log(`${label} Cloudy Pixels: ${cloudy.toLocaleString()}`);
    console.log(`${label} Cloud Coverage: ${coverage.toFixed(2)}%`);
    return coverage;
  };

  const morningCoverage = await calculateCloudCoverage(morningImage, 'Morning');
  const afternoonCoverage = await calculateCloudCoverage(afternoonImage, 'Afternoon');

  // 4. Validation & Final Answer
  if (morningCoverage === null || afternoonCoverage === null) {
    console.log('C3'); // Calculation failed for one of the coverages
    return;
  }

  if (morningCoverage === 0 && afternoonCoverage === 0) {
    console.log('Both morning and afternoon are clear, so no decrease in fog coverage.');
    console.log('B');
    return;
  }

  if (morningCoverage > afternoonCoverage) {
    console.log('A'); // Fog coverage decreased
  } else {
    console.log('B'); // Fog coverage did not decrease (stayed same or increased)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
